115| \begin{method}[测量微小宽度]\label{met:g12:light-as-wave:hairwidth}
116|=\begin{enumerate}
117|   \item 将头发横跨在激光束上，在
118|         测得距离 $D$（几米）处放置屏幕。
119|   \item 测量中央亮带的宽度 $L$，即两侧暗纹之间的距离。
120|   \item 由 $L = 2\lambda D/d$ 可得 $d = 2\lambda D/L$——头发越细，
121|         图样越大。
122|=\end{enumerate}
123|=\end{method}
